def collapse_whitespace(s: str) -> str:
    """Collapse runs of ASCII whitespace into one space and strip ends."""
    result = []
    prev_was_space = False
    for ch in s:
        # Only these ASCII whitespace chars are collapsed
        if ch in (' ', '\t', '\n', '\r', '\x0b', '\x0c'):
            if not prev_was_space:
                result.append(' ')
                prev_was_space = True
        else:
            result.append(ch)
            prev_was_space = False
    # Strip leading/trailing spaces only
    return ''.join(result).strip(' ')
